<template>
  <div class="city-list" v-if="cityInfo">
    <mt-index-list>
      <div class="current-select" v-show="currentCity.length > 0">
        <div class="title">最近访问的城市</div>
        <div class="list">
          <span class="item" v-for="(item, index) in currentCity" :key="index" @click="selectCity(item)">{{item.area_name}}</span>
        </div>
      </div>
      <mt-index-section :index="listName" v-for="(cityList, listName) in cityInfo.all_city" :key="listName">
        <mt-cell :title="item.area_name" v-for="(item, index) in cityList" :key="index" @click.native="selectCity(item)"></mt-cell>
      </mt-index-section>
    </mt-index-list>
  </div>
</template>

<script>

export default {
  name: 'CityList',
  data () {
    return {
      cityInfo: '',
      currentCity: []
    }
  },
  created () {
    this.getCityList()
    this.currentCity = this.$util.storage.get('cityList') ? this.$util.storage.get('cityList') : []
  },
  methods: {
    selectCity (item) {
      item.child = []
      for (let i = 0; i < this.currentCity.length; i++) {
        if (this.currentCity[i].area_id == item.area_id) {
          this.currentCity.splice(i, 1)
          break
        }
      }
      this.currentCity.splice(0, 0, item)
      this.$util.storage.set('cityList', this.currentCity)
      this.$global.city = item
      this.$router.go(-1)
    },
    async getCityList () {
      let res = await this.$api.getCity()
      if (!res) return
      this.cityInfo = res
    }
  }
}
</script>

<style lang="stylus">
.city-list
  .current-select
    background #fff
    .title
      font-size 16px
      padding 15px 10px
    .list
      flexbox()
      flex-wrap wrap
      padding-left 10px
      .item
        background #f4f4f4
        padding 8px 16px
        margin 0 15px 15px 0
        border-radius 2px
  .mint-indexlist-content
    margin-right 0 !important
    .mint-indexsection-index
      background #f4f4f4
    .mint-cell
      border-bottom 1PX solid #f4f4f4
  .mint-indexlist-nav
    border-left none
    background transparent
</style>
